import app from 'flarum/admin/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
export default class MassDeleteDiscussionModal extends FormModal {
  oninit(vnode) {
    super.oninit(vnode);
    this.selectedDiscussions = vnode.attrs.selectedDiscussions;
  }
  className() {
    return 'MassDeleteDiscussionModal Modal--small';
  }
  title() {
    return app.translator.trans('walsgit-recycle-bin.admin.mass_delete_modal.title');
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("p", null, app.translator.trans('walsgit-recycle-bin.admin.mass_delete_modal.text_start'), " ", m("strong", null, this.selectedDiscussions.size), ' ', app.translator.trans('walsgit-recycle-bin.admin.mass_delete_modal.text_end')), m("div", {
      className: "Form-group"
    }, m(Button, {
      className: 'Button Button--primary Button--block',
      onclick: () => this.onsubmit()
    }, app.translator.trans('walsgit-recycle-bin.admin.mass_delete_modal.submit_button'))));
  }
  onsubmit() {
    this.loading = true;
    app.request({
      method: 'POST',
      url: `${app.forum.attribute('apiUrl')}/recycle-bin/mass-discussions`,
      body: {
        action: 'delete',
        ids: Array.from(this.selectedDiscussions)
      }
    }).then(() => {
      this.hide();
      if (this.attrs.onSuccess) {
        this.attrs.onSuccess();
      }
      m.redraw();
      app.alerts.show({
        type: 'success'
      }, app.translator.trans('walsgit-recycle-bin.admin.mass_delete_modal.success'));
    }).catch(() => {
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('walsgit-recycle-bin', 'admin/components/MassDeleteDiscussionModal', MassDeleteDiscussionModal);